114	/** What a server advertised that it should not have, and what it did not advertise. */
115	export interface ToolSetMismatch {
116	  readonly server: string;
117	  /** Advertised and not expected — the direction a guard failing open takes. */
118	  readonly unexpected: readonly string[];
119	  /** Expected and not advertised — a server that has lost a tool, or has not started. */
120	  readonly missing: readonly string[];
121	}
122	
123	/**
124	 * The tools a server contributed, with the core's own removed.
125	 *
126	 * Takes what the agent was handed for a definition naming ONE server, which is why it
127	 * can be a filter rather than an attribution: with one server in the definition every
128	 * remaining name is that server's. Keying on `server__` instead would read an
129	 * `unprefixed` server's six tools as zero — the shape `probes/tool-servers.ts` was
130	 * caught by once already.
131	 */
132	export function serverContributed(advertised: readonly string[]): string[] {
133	  return advertised.filter((name) => !name.startsWith(CORE_TOOL_PREFIX));
134	}
135	
136	/**
137	 * Hold one server's advertised tools to its set, exactly.
138	 *
139	 * Both directions, and the less obvious one earns its place: a `missing` tool is how
140	 * a server that came up empty, or one whose allowlist has gone from narrowing to
141	 * forbidding, becomes a failure rather than a pass over an empty list. An expectation
142	 * that only refused extras would be satisfied by a server offering nothing.
143	 */
144	export function compareToolSet(expected: ExactToolSet, advertised: readonly string[]): ToolSetMismatch | undefined {
145	  const seen = new Set(serverContributed(advertised));
146	  const allowed = new Set(expected.tools);
147	  const unexpected = [...seen].filter((name) => !allowed.has(name)).sort();
148	  const missing = expected.tools.filter((name) => !seen.has(name));
149	  if (unexpected.length === 0 && missing.length === 0) return undefined;
150	  return { server: expected.server, unexpected, missing };
151	}
152	
153	/** One line a person can act on, naming what changed and what it costs. */
154	export function describeMismatch(expected: ExactToolSet, mismatch: ToolSetMismatch): string {
155	  const parts: string[] = [];
156	  if (mismatch.unexpected.length > 0) {
157	    parts.push(`advertises ${mismatch.unexpected.join(", ")}, which it must not`);
158	  }
159	  if (mismatch.missing.length > 0) {
160	    parts.push(`does not advertise ${mismatch.missing.join(", ")}, which it must`);
161	  }
162	  return (
163	    `${expected.server} ${parts.join("; and ")}. Expected exactly {${expected.tools.join(", ")}}. ` +
164	    expected.promise
165	  );
166	}

