 * per program. The expectation is `EXACT_DELEGATE_TOOL_SETS`, never the server's own
 * source — a check that read `defineMcpTool` out of `files.ts` would agree with
 * whatever the server had become.
 *
 * One program, started once: `files` and `files_readonly` are the same script, and
 * both answers would be identical.
 */
import { describe, expect, test } from "bun:test";
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { EXACT_DELEGATE_TOOL_SETS, type DelegateServerTools } from "../../src/domain/machinery/delegates.ts";
import { hermeticEnv } from "../../src/entrypoints/machinery/testing/harness.ts";

const MCP_DIR = join(process.cwd(), "src/entrypoints/tools/mcp");
const ROOT_PREFIX = "${ATOMATON_MACHINERY_ROOT:-.}/";

function scriptOf(args: unknown): string | undefined {
  if (!Array.isArray(args)) return undefined;
  const script = args.map(String).find((arg) => arg.startsWith(ROOT_PREFIX) && arg.endsWith(".ts"));
  if (script === undefined) return undefined;
  // `${ATOMATON_MACHINERY_ROOT:-.}/.github/atomaton-runtime/tools/mcp/files.ts` -> files.ts
